+                assertThat(downloadFileError, is(instanceOf(CorruptIndexException.class)));
+                break;
+            case TRUNCATED_FILE:
+                assertThat(downloadFileError, is(instanceOf(EOFException.class)));
+                break;
+            case FETCH_ERROR:
+                assertThat(downloadFileError, is(instanceOf(RuntimeException.class)));
+                break;
+            default:
