+                            if (randomBoolean()) {
+                                // Return random data
+                                for (int i = 0; i < len; i++) {
+                                    b[off + i] = randomByte();
+                                }
+                                return len;
+                            } else {
+                                if (randomBoolean()) {
+                                    throw new IOException("Unable to read blob " + blobName);
+                                } else {
+                                    // Skip some file chunks
+                                    int read = super.read(b, off, len);
+                                    return read / 2;
+                                }
+                            }
+                        }
+                    };
+                }
+            };
